import { zstdCompressSync, zstdDecompressSync } from "node:zlib";
const orig = JSON.stringify({hello:"world", model:"test"});
const c = zstdCompressSync(Buffer.from(orig));
console.log("compressed len", c.length, "magic", c[0].toString(16), c[1].toString(16), c[2].toString(16), c[3].toString(16));
const d = zstdDecompressSync(c);
console.log("roundtrip", Buffer.from(d).toString() === orig);
// Bun global
const c2 = Bun.zstdCompressSync(Buffer.from(orig));
console.log("bun compressed len", c2.length);
console.log("bun roundtrip", Buffer.from(Bun.zstdDecompressSync(c2)).toString() === orig);
// check magic bytes for zstd frame: 28 b5 2f fd
console.log("expected magic 28 b5 2f fd");
' 2>&1
node -e '
const z=require("node:zlib");
console.log("node version", process.version);
console.log(typeof z.zstdDecompressSync);
const orig = JSON.stringify({hello:"world"});
const c = z.zstdCompressSync(Buffer.from(orig));
console.log(c.slice(0,4));
console.log(z.zstdDecompressSync(c).toString()===orig);
' 2>&1","description":"Test zstd roundtrip APIs"}

