{"command":"bun -e '
import { zstdCompressSync } from "node:zlib";
const payload = JSON.stringify({choices:[{message:{content:"hi"}}], usage:{prompt_tokens:1,completion_tokens:1,total_tokens:2}});
const compressed = zstdCompressSync(Buffer.from(payload));
// mock upstream that returns zstd
const srv = Bun.serve({
  port: 0,
  fetch(req){
    return new Response(compressed, { headers: { "Content-Type":"application/json", "Content-Encoding":"zstd" }});
  }
});
const url = `http://127.0.0.1:${srv.port}/`;
const res = await fetch(url);
console.log("content-encoding from fetch:", res.headers.get("content-encoding"));
console.log("content-type:", res.headers.get("content-type"));
try {
  const j = await res.json();
  console.log("res.json succeeded:", JSON.stringify(j).slice(0,100));
} catch(e){ console.log("res.json failed:", e.message); }
try {
  const res2 = await fetch(url);
  const txt = await res2.text();
  console.log("res.text len", txt.length, "first20", JSON.stringify(txt.slice(0,20)));
} catch(e){ console.log("res.text failed:", e.message); }
srv.stop(true);
' 2>&1","description":"Test fetch auto-decompression of zstd"}

