{"command":"bun -e '
import { zstdCompressSync } from "node:zlib";
const payload = JSON.stringify({model:"test-model", input:[], stream:false});
const compressed = zstdCompressSync(Buffer.from(payload));
const srv = Bun.serve({
  port: 0,
  async fetch(req){
    console.log("inbound ce:", req.headers.get("content-encoding"));
    console.log("inbound ct:", req.headers.get("content-type"));
    const buf = Buffer.from(await req.arrayBuffer());
    console.log("raw len", buf.length, "magic", buf.slice(0,4).toString("hex"));
    try {
      const j = await req.json();
      console.log("req.json succeeded", JSON.stringify(j).slice(0,80));
    } catch(e){ console.log("req.json failed:", e.message); }
    return Response.json({ok:true});
  }
});
const url = `http://127.0.0.1:${srv.port}/`;
// case 1: with content-encoding zstd
let r = await fetch(url, {method:"POST", headers:{"Content-Type":"application/json","Content-Encoding":"zstd"}, body: compressed});
console.log("case1 status", r.status, await r.text());
// case 2: without ce, raw zstd bytes
r = await fetch(url, {method:"POST", headers:{"Content-Type":"application/json"}, body: compressed});
console.log("case2 status", r.status, await r.text());
srv.stop(true);
' 2>&1","description":"Test inbound zstd handling by Bun"}

