{"content":"// Content-Encoding + magic-sniff decompression for inbound client bodies
// and upstream provider bodies. Zero npm dependencies (node:zlib only).
// Bun's fetch auto-decompresses upstream Content-Encoding, but Bun.serve
// does NOT decompress inbound bodies, and some providers send raw zstd
// frames without a Content-Encoding header. Sniffing the frame magic keeps
// both paths correct without double-decoding.
import {
  brotliDecompressSync,
  gunzipSync,
  inflateSync,
  zstdDecompressSync,
} from "node:zlib";

export function isZstdFrame(bytes) {
  return (
    bytes &&
    bytes.length >= 4 &&
    bytes[0] === 0x28 &&
    bytes[1] === 0xb5 &&
    bytes[2] === 0x2f &&
    bytes[3] === 0xfd
  );
}

export function isGzipFrame(bytes) {
  return bytes && bytes.length >= 2 && bytes[0] === 0x1f && bytes[1] === 0x8b;
}

export function parseContentEncodings(header) {
  if (!header) return [];
  return String(header)
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function tryZstd(buf) {
  try {
    const out = zstdDecompressSync(buf);
    if (out && out.length) return Buffer.from(out);
  } catch {}
  return undefined;
}

function tryGzip(buf) {
  try {
    const out = gunzipSync(buf);
    if (out) return Buffer.from(out);
  } catch {}
  return undefined;
}

function tryDeflate(buf) {
  try {
    const out = inflateSync(buf);
    if (out) return Buffer.from(out);
  } catch {}
  return undefined;
}

function tryBrotli(buf) {
  try {
    const out = brotliDecompressSync(buf);
    if (out) return Buffer.from(out);
  } catch {}
  return undefined;
}

