    const raw = Buffer.from(await res.arrayBuffer());
    const decoded = decompressUpstreamBody(raw, res.headers.get("content-encoding"));
    return new TextDecoder().decode(decoded);
  } catch {
    return "";
  }
}

// Resolve the byte stream to feed SSE parsers. Pass-through when the body
// is plain text (preserves true streaming); buffers + decompresses only
// when a raw compressed frame was sent without a Content-Encoding header
// (fetch would otherwise leave binary bytes in the stream).
export async function decodedUpstreamStream(res) {
  const body = res.body;
  if (!body) return body;
  const encodings = parseContentEncodings(res.headers.get("content-encoding"));
  const headerClaimsCompressed = encodings.some((e) =>
    ["zstd", "gzip", "x-gzip", "deflate", "br"].includes(e),
  );
  if (headerClaimsCompressed) {
    // Fetch already decoded this case; keep the live stream.
    return body;
  }
  const reader = body.getReader();
  const chunks = [];
  let headLen = 0;
  // Peek enough bytes to sniff the magic without losing data.
  while (headLen < 4) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    headLen += value ? value.length : 0;
  }
  if (!chunks.length) {
    try {
      reader.releaseLock();
    } catch {}
    return new ReadableStream({
      start(controller) {
        controller.close();
      },
    });
  }
  const head = Buffer.concat(chunks.map((c) => Buffer.from(c)));
  const compressed = isZstdFrame(head) || isGzipFrame(head);
  if (!compressed) {
    // Replay peeked bytes then pump the rest live.
    return new ReadableStream({
      async start(controller) {
        for (const c of chunks) controller.enqueue(c);
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            controller.enqueue(value);
          }
        } catch (e) {
          try {
            controller.error(e);
          } catch {}
          return;
        }
        try {
          controller.close();
        } catch {}
      },
    });
  }
  // Raw compressed frame: buffer the remainder, decompress once, emit text.
  const rest = [];
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      rest.push(Buffer.from(value));
    }
  } catch {}
  const combined = Buffer.concat([head, ...rest]);
  let decompressed = decompressBytes(combined, null);
  if (!decompressed) decompressed = combined;
  const out = new Uint8Array(decompressed);
  return new ReadableStream({
    start(controller) {
      controller.enqueue(out);
      controller.close();
    },
  });
}
