import { zstdCompressSync, gzipSync } from "node:zlib";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

// setup mock upstream (plain)
const mock = Bun.serve({
  port: 0,
  async fetch(req){
    const body = await req.json();
    return Response.json({
      id:"chatcmpl-mock", object:"chat.completion", created: 1, model: body.model,
      choices:[{index:0, message:{role:"assistant", content:"mock answer hasImage=false carried=false effort="+ (body.reasoning_effort||"none"), reasoning_content:"mock reasoning", tool_calls:[
        {id:"call_1", type:"function", function:{name:"shell", arguments:"{\"cmd\":\"echo hi\"}"}},
        {id:"call_2", type:"function", function:{name:"collaboration__spawn_agent", arguments:"{}"}}
      ]}, finish_reason:"tool_calls"}],
      usage:{prompt_tokens:25, completion_tokens:30, total_tokens:55}
    });
  }
});
const dir = mkdtempSync(path.join(tmpdir(), "codextras-zstd-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({
  gateway:{port:0, pathPrefix:"/_codextras"},
  providers:[{id:"mock", type:"openai-chat", baseUrl:`http://127.0.0.1:${mock.port}`, apiKeyEnv:"CODEXTRAS_TEST_KEY", quirks:{efforts:{low:"low",high:"high",max:"max"}}}],
  models:[{alias:"test-model", displayName:"Test", provider:"mock", upstreamModel:"mock-upstream", contextWindow:100000, efforts:["low","high","max"], defaultEffort:"high", inputModalities:["text","image"], reasoningContent:true}]
}));
process.env.CODEXTRAS_TEST_KEY="sk-test";
process.env.CODEXTRAS_CONFIG=configPath;
const { createServer } = await import("./src/server.mjs");
const { loadConfig } = await import("./src/config.mjs");
const secret="testsecret123";
const server = createServer(loadConfig(), secret);
const base=`http://127.0.0.1:${server.port}/_codextras/${secret}`;

function user(t){ return {type:"message", role:"user", content:[{type:"input_text", text:t}]}; }

// 1. plain baseline
let res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({model:"test-model", input:[user("hi")], stream:false})});
console.log("plain status", res.status);

// 2. zstd with header
let payload = JSON.stringify({model:"test-model", input:[user("hi zstd")], stream:false});
let comp = zstdCompressSync(Buffer.from(payload));
console.log("zstd magic", Buffer.from(comp).slice(0,4).toString("hex"));
