{"command":"bun -e '
import { zstdCompressSync } from "node:zlib";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

// upstream that returns zstd-compressed JSON without Content-Encoding
const zstdMock = Bun.serve({
  port: 0,
  async fetch(req){
    const body = await req.json().catch(()=>({}));
    const payload = {
      id:"chatcmpl-mock", object:"chat.completion", created:1, model: body.model,
      choices:[{index:0, message:{role:"assistant", content:"zstd upstream answer", reasoning_content:"mock reasoning", tool_calls:[]}, finish_reason:"stop"}],
      usage:{prompt_tokens:10, completion_tokens:5, total_tokens:15}
    };
    const comp = zstdCompressSync(Buffer.from(JSON.stringify(payload)));
    const url = new URL(req.url);
    if(url.searchParams.get("mode")==="withheader"){
      return new Response(comp, {headers:{"Content-Type":"application/json","Content-Encoding":"zstd"}});
    }
    // raw without header
    return new Response(comp, {headers:{"Content-Type":"application/json"}});
  }
});
console.log("zstdMock port", zstdMock.port);

for(const mode of ["raw","withheader"]){
  const dir = mkdtempSync(path.join(tmpdir(), "codextras-zstd-up-"));
  const configPath = path.join(dir, "codextras.json");
  // point baseUrl with query to control mode? baseUrl + /chat/completions, so embed query via baseUrl? chatUrl appends /chat/completions, query would be lost. Instead use two mocks or header check.
  // Simpler: create mock that checks a custom header we send? But gateway doesnt forward custom. Instead test both by restarting mock behavior via env? Easiest: test raw first, then withheader by changing mock fetch via variable.
  break;
}

// Test raw mode
{
  const dir = mkdtempSync(path.join(tmpdir(), "codextras-zstd-up2-"));
  const configPath = path.join(dir, "codextras.json");
  writeFileSync(configPath, JSON.stringify({
    gateway:{port:0, pathPrefix:"/_codextras"},
    providers:[{id:"mock", type:"openai-chat", baseUrl:`http://127.0.0.1:${zstdMock.port}`, apiKeyEnv:"CODEXTRAS_TEST_KEY"}],
    models:[{alias:"test-model", displayName:"Test", provider:"mock", upstreamModel:"mock-upstream", contextWindow:100000, efforts:["high"], defaultEffort:"high", inputModalities:["text"]}]
  }));
  process.env.CODEXTRAS_TEST_KEY="sk-test";
  process.env.CODEXTRAS_CONFIG=configPath;
  // need fresh import with new config? loadConfig reads env path each time, createServer uses passed config
  const { createServer } = await import("./src/server.mjs");
  const { loadConfig } = await import("./src/config.mjs");
  const server = createServer(loadConfig(), "s3");
  const base=`http://127.0.0.1:${server.port}/_codextras/s3`;
  function user(t){ return {type:"message", role:"user", content:[{type:"input_text", text:t}]}; }
  let res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({model:"test-model", input:[user("hi")], stream:false})});
  console.log("upstream raw zstd status", res.status);
  const d = await res.json();
  console.log("upstream raw output", JSON.stringify(d.output).slice(0,200));
  console.log("has zstd answer?", JSON.stringify(d).includes("zstd upstream answer") ? "YES" : "NO - FAIL");
  server.stop(true);
}
zstdMock.stop(true);
' 2>&1","description":"Test upstream zstd without header"}

