import { zstdCompressSync } from "node:zlib";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

async function testMode(mode){
  const mock = Bun.serve({
    port: 0,
    async fetch(req){
      const sse = "data: "+JSON.stringify({choices:[{index:0, delta:{content:"streamed hello"}}]})+"\n\ndata: "+JSON.stringify({choices:[], usage:{prompt_tokens:5, completion_tokens:5, total_tokens:10}})+"\n\ndata: [DONE]\n\n";
      if(mode==="raw"){
        const comp = zstdCompressSync(Buffer.from(sse));
        return new Response(comp, {headers:{"Content-Type":"text/event-stream"}});
      } else if(mode==="withheader"){
        const comp = zstdCompressSync(Buffer.from(sse));
        return new Response(comp, {headers:{"Content-Type":"text/event-stream","Content-Encoding":"zstd"}});
      } else {
        return new Response(sse, {headers:{"Content-Type":"text/event-stream"}});
      }
    }
  });
  const dir = mkdtempSync(path.join(tmpdir(), "codextras-stream-"));
  const configPath = path.join(dir, "codextras.json");
  writeFileSync(configPath, JSON.stringify({
    gateway:{port:0, pathPrefix:"/_codextras"},
    providers:[{id:"mock", type:"openai-chat", baseUrl:`http://127.0.0.1:${mock.port}`, apiKeyEnv:"K"}],
    models:[{alias:"test-model", displayName:"Test", provider:"mock", upstreamModel:"m", contextWindow:100000, efforts:["high"], defaultEffort:"high", inputModalities:["text"]}]
  }));
  process.env.CODEXTRAS_TEST_KEY="K";
  process.env.CODEXTRAS_CONFIG=configPath;
  const { createServer } = await import("./src/server.mjs");
  const { loadConfig } = await import("./src/config.mjs");
  const server = createServer(loadConfig(), "s3");
  const base=`http://127.0.0.1:${server.port}/_codextras/s3`;
  const res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({model:"test-model", input:[{type:"message", role:"user", content:[{type:"input_text", text:"hi"}]}], stream:true})});
  const txt = await res.text();
  const ok = txt.includes("streamed hello") && txt.includes("response.completed");
  console.log(`stream mode=${mode} status=${res.status} ok=${ok ? "YES" : "NO FAIL"}`);
  if(!ok) console.log(txt.slice(0,500));
  server.stop(true); mock.stop(true);
}
await testMode("plain");
await testMode("raw");
await testMode("withheader");
' 2>&1","description":"Test streaming zstd variants"}

