{"command":"bun -e '
import { zstdCompressSync } from "node:zlib";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

// Responses-wire mock + error mock
const mockResponses = Bun.serve({
  port: 0,
  async fetch(req){
    const body = await req.json().catch(()=>({}));
    const txt = JSON.stringify(body);
    if(txt.includes("ERR_ZSTD")){
      const errPayload = JSON.stringify({error:{message:"upstream zstd boom"}});
      const comp = zstdCompressSync(Buffer.from(errPayload));
      return new Response(comp, {status:500, headers:{"Content-Type":"application/json"}});
    }
    if(txt.includes("RESP_STREAM_RAW")){
      const sse = `event: response.created\ndata: ${JSON.stringify({type:"response.created", response:{id:"r1", status:"in_progress", model:"m", output:[]}})}\n\nevent: response.completed\ndata: ${JSON.stringify({type:"response.completed", response:{id:"r1", status:"completed", model:"m", output:[{type:"message", id:"m1", role:"assistant", status:"completed", content:[{type:"output_text", text:"resp streamed zstd", annotations:[]}]}]}})}\n\ndata: [DONE]\n\n`;
      const comp = zstdCompressSync(Buffer.from(sse));
      return new Response(comp, {headers:{"Content-Type":"text/event-stream"}});
    }
    const out = {
      id:"resp_1", object:"response", created_at:1, status:"completed", model: body.model,
      output:[{type:"message", id:"m1", role:"assistant", status:"completed", content:[{type:"output_text", text:"responses answer "+(txt.includes("ZSTD_UP")?"zstd-ok":"plain"), annotations:[]}]}],
      usage:{input_tokens:5, output_tokens:5, total_tokens:10}
    };
    if(txt.includes("ZSTD_UP")){
      const comp = zstdCompressSync(Buffer.from(JSON.stringify(out)));
      // raw without header
      return new Response(comp, {headers:{"Content-Type":"application/json"}});
    }
    return Response.json(out);
  }
});
const dir = mkdtempSync(path.join(tmpdir(), "codextras-resp-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({
  gateway:{port:0, pathPrefix:"/_codextras"},
  providers:[{id:"mockr", type:"openai-responses", baseUrl:`http://127.0.0.1:${mockResponses.port}`, apiKeyEnv:"K"}],
  models:[{alias:"rmodel", displayName:"R", provider:"mockr", upstreamModel:"m", contextWindow:100000, efforts:["high"], defaultEffort:"high", inputModalities:["text"]}]
}));
process.env.CODEXTRAS_TEST_KEY="K";
process.env.CODEXTRAS_CONFIG=configPath;
const { createServer } = await import("./src/server.mjs");
const { loadConfig } = await import("./src/config.mjs");
const server = createServer(loadConfig(), "s3");
const base=`http://127.0.0.1:${server.port}/_codextras/s3`;
function user(t){ return {type:"message", role:"user", content:[{type:"input_text", text:t}]}; }

// non-stream zstd upstream
let res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({model:"rmodel", input:[user("hi ZSTD_UP")], stream:false})});
let d = await res.json();
console.log("responses zstd upstream", res.status, JSON.stringify(d).includes("zstd-ok")?"YES":"NO "+JSON.stringify(d).slice(0,300));

// stream raw zstd
res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({model:"rmodel", input:[user("hi RESP_STREAM_RAW")], stream:true})});
let txt = await res.text();
console.log("responses stream raw", res.status, txt.includes("resp streamed zstd")?"YES":"NO "+txt.slice(0,500));

// error zstd
res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({model:"rmodel", input:[user("hi ERR_ZSTD")], stream:false})});
d = await res.json().catch(()=>null);
console.log("responses err zstd", res.status, JSON.stringify(d).includes("upstream zstd boom")?"YES":"NO "+JSON.stringify(d).slice(0,300));

// inbound zstd to responses wire
let payload = JSON.stringify({model:"rmodel", input:[user("hi inbound")], stream:false});
let comp = zstdCompressSync(Buffer.from(payload));
res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json","Content-Encoding":"zstd"}, body: comp});
d = await res.json();
console.log("inbound zstd to responses", res.status, d.output?"YES":"NO "+JSON.stringify(d).slice(0,300));

server.stop(true); mockResponses.stop(true);
' 2>&1","description":"Test Responses wire zstd paths"}

